    f.success_metric && lines.push(`Success metric: ${f.success_metric}`);

    lines.push('');
    lines.push('Output:');

    // A) Canonical + scope setting
    lines.push(`A) Canonical HMW (${scope} scope):`);
    lines.push(canonical);

    // B) Variant set using verb palette and scope shifts
