    const lc = (s) => String(s||"").toLowerCase();

    // Canonical Doblin types and grouping
    const TYPES = [
      "Profit Model","Network","Structure","Process",
      "Product Performance","Product System",
      "Service","Channel","Brand","Customer Engagement"
    ];
    const GROUP = {
      "Profit Model":"Configuration","Network":"Configuration","Structure":"Configuration","Process":"Configuration",
      "Product Performance":"Offering","Product System":"Offering",
      "Service":"Experience","Channel":"Experience","Brand":"Experience","Customer Engagement":"Experience"
    };

    // Lightweight normalizer for common synonyms
    const normalizeType = (t) => {
      const s = lc(t).replace(/[-_]/g," ").trim();
      if (/profit|pricing|revenue|moneti/.test(s)) return "Profit Model";
      if (/network|partner|ecosys|sdk|platform/.test(s)) return "Network";
      if (/structur|org|talent|incent|hub|studio/.test(s)) return "Structure";
      if (/process|ops|devops|pipeline|manufact|delivery|automation/.test(s)) return "Process";
      if (/product system|ecosystem|bundle|kit|api|add-?on|app store/.test(s)) return "Product System";
      if (/product|perf(ormance)?|feature|quality|usab/.test(s)) return "Product Performance";
      if (/service|support|warran|education|success/.test(s)) return "Service";
      if (/channel|distribut|marketplace|embedded/.test(s)) return "Channel";
      if (/brand|story|meaning|trust|signal|proof/.test(s)) return "Brand";
      if (/engage|community|gamif|personaliz|habit|loyal/.test(s)) return "Customer Engagement";
      // Fallback to title case of input if matches known
      const guess = TYPES.find(x => lc(x) === s);
      return guess || t.trim();
    };

    const extractTypes = (text) => {
      const m = String(text||"").match(/types?\s*:\s*([^;]+)(;|$)/i);
      if (!m) return [];
      return m[1].split(/\s*,\s*/).map(normalizeType).filter(Boolean);
    };

    const parseLaunches = (v) => lines(v).map(raw => {
      const name = raw.split(/—|--|–/)[0]?.trim() || raw;
      const types = extractTypes(raw).filter(t => TYPES.includes(t));
      return { name, types };
    });

    const parseIdeas = (v) => lines(v).map(raw => {
      const name = raw.split(/—|--|–/)[0]?.trim() || raw;
      const types = extractTypes(raw).filter(t => TYPES.includes(t));
      const tactics = (raw.match(/tactics?\s*:\s*([^;]+)(;|$)/i)?.[1] || "")
        .split(/\s*,\s*/).map(x=>x.trim()).filter(Boolean);
      const metrics = (raw.match(/metrics?\s*:\s*([^;]+)(;|$)/i)?.[1] || "")
        .split(/\s*,\s*/).map(x=>x.trim()).filter(Boolean);
      return { name, types, tactics, metrics, raw };
    });

